<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {untrack,type Snippet} from 'svelte';
 import {Search,ListFilter,Box,Users,UserRound,Layers,X} from 'lucide-svelte';
 import type {ResourceKind} from './resources';
 import {catalogKinds,catalogCategories,type CatalogCategory} from './catalog';
 let {kind,kinds=['object','npc','player','tile','railing'],query=$bindable(''),category=$bindable('all'),scroll=$bindable(0),count=0,busy=false,loading=false,contained=false,scrollKey=kind,onkindchange,actions,children}:{kind:ResourceKind;kinds?:ResourceKind[];query?:string;category?:CatalogCategory;scroll?:number;count?:number;busy?:boolean;loading?:boolean;contained?:boolean;scrollKey?:string;onkindchange?:(kind:ResourceKind)=>void;actions?:Snippet;children:Snippet}=$props();
 const icons={object:Box,npc:Users,player:UserRound,tile:Layers,railing:Layers};
 const hasCategories=$derived(kind==='object'||kind==='npc');
 const activeCategory=$derived(hasCategories&&category!=='all');
 let filtersOpen=$state(false),filterMenu:HTMLDetailsElement|undefined=$state(),viewport:HTMLDivElement|undefined=$state();
 $effect(()=>{scrollKey;count;loading;if(contained&&viewport&&!loading)viewport.scrollTop=untrack(()=>scroll);});
 function resetScroll(){scroll=0;viewport?.scrollTo({top:0});}
 function outside(e:PointerEvent){if(filtersOpen&&e.target instanceof Node&&!filterMenu?.contains(e.target))filtersOpen=false;}
 function filterKey(e:KeyboardEvent){if(e.key==='Escape'&&filtersOpen){e.preventDefault();e.stopPropagation();filtersOpen=false;filterMenu?.querySelector('summary')?.focus();}}
</script>
<svelte:window onpointerdown={outside}/>
<div class="catalog-browser" class:contained>
 <div class="controls">
  {#if onkindchange&&kinds.length>1}<div class="types" role="group" aria-label={ui.text("Tipos del catálogo")}>{#each catalogKinds.filter(item=>kinds.includes(item.id)) as item}{@const Icon=icons[item.id]}<button type="button" disabled={busy} aria-label={ui.text(item.label)} aria-pressed={kind===item.id} title={ui.text(item.label)} onclick={()=>onkindchange?.(item.id)}><Icon size={15}/><span>{item.id==='player'?ui.text('PJ'):ui.text(item.label)}</span></button>{/each}</div>{/if}
  <div class="search-row">
   <label class="search"><Search size={15}/><input aria-label={ui.text("Buscar recurso")} placeholder={ui.text("Buscar recursos…")} disabled={busy} bind:value={query} oninput={resetScroll}/><span class="count" role="status" aria-label={ui.text("{arg0} recursos encontrados",{arg0:count})}>{loading?'…':count}</span></label>
   {#if hasCategories}<details class="filter-menu" bind:this={filterMenu} bind:open={filtersOpen}><summary onkeydown={filterKey} aria-label={ui.text("Filtrar por categoría")} title={ui.text("Filtrar por categoría")} class:active={activeCategory}><ListFilter size={17}/>{#if activeCategory}<span class="filter-dot"></span>{/if}</summary><div class="filter-options"><label>{ui.text("Categoría")}<select onkeydown={filterKey} aria-label={ui.text("Categoría del catálogo")} disabled={busy} bind:value={category} onchange={()=>{resetScroll();filtersOpen=false;filterMenu?.querySelector('summary')?.focus();}}>{#each catalogCategories as item}<option value={item.id}>{ui.text(item.label)}</option>{/each}</select></label></div></details>{/if}
   {#if actions}<div class="actions">{@render actions()}</div>{/if}
  </div>
  {#if activeCategory}<button type="button" class="category-chip" disabled={busy} title={ui.text("Quitar filtro de categoría")} aria-label={ui.text("Quitar filtro de categoría")} onclick={()=>{category='all';resetScroll();}}>{ui.text(catalogCategories.find(c=>c.id===category)?.label??'')}<X size={12}/></button>{/if}
 </div>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (The scroll region needs keyboard focus for PageUp and PageDown.) -->
 <div class="resources" role="region" aria-label={ui.text("Listado de recursos")} tabindex={contained?0:undefined} bind:this={viewport} onscroll={()=>{if(contained&&!loading&&viewport)scroll=viewport.scrollTop;}}>{@render children()}</div>
</div>
<style>
 .catalog-browser{display:flex;flex-direction:column;gap:10px;min-height:0;min-width:0}.contained{height:100%;flex:1}.controls{flex:none;display:flex;flex-direction:column;gap:8px;position:relative;z-index:3}.types{display:flex;gap:3px;min-width:0}.types button{flex:1;min-width:0;display:flex;justify-content:center;align-items:center;gap:4px;padding:7px 3px;min-height:34px;font:inherit;font-size:11px;border:1px solid transparent;border-radius:6px;background:transparent;color:#677a5c;cursor:pointer}.types button[aria-pressed=true]{background:#e5edda;color:#38552c;border-color:#d4e0c8}.types span{white-space:nowrap}.search-row{display:flex;align-items:center;gap:4px;min-width:0}.search{display:flex;align-items:center;gap:6px;margin:0;padding:0 8px;flex:1;min-width:0;border:1px solid #d8e0ce;border-radius:7px;background:#fff;color:#7b8973}.search input{flex:1;min-width:0;border:0;padding:9px 0;background:transparent;font:inherit;font-size:12px;color:#3e5334;outline:none}.search:focus-within{outline:2px solid #74994e;outline-offset:2px}.count{flex:none;font-size:10px;color:#76866e}.filter-menu,.actions{flex:none}.filter-menu{position:relative}.filter-menu summary{display:grid;place-items:center;position:relative;cursor:pointer;list-style:none;width:34px;height:34px;border:1px solid transparent;border-radius:7px;color:#607359}.filter-menu summary::-webkit-details-marker{display:none}.filter-menu[open] summary,.filter-menu summary.active{background:#e5edda;border-color:#cadabd;color:#38552c}.filter-dot{position:absolute;right:4px;top:4px;width:5px;height:5px;border-radius:50%;background:#476238}.filter-options{position:absolute;right:0;top:calc(100% + 5px);width:232px;max-width:calc(100vw - 52px);padding:12px;border:1px solid #d6e1ce;border-radius:9px;background:#fff;box-shadow:0 8px 26px #263b2e20;z-index:10;box-sizing:border-box}.filter-options label{display:grid;gap:8px;font-size:12px;color:#486238}.filter-options select{min-width:0;width:100%;box-sizing:border-box;padding:8px;border:1px solid #d8e0ce;border-radius:7px;background:#fff;font:inherit;color:#3e5334}.category-chip{align-self:flex-start;display:flex;align-items:center;gap:6px;font:inherit;font-size:10px;padding:4px 7px;border:1px solid #cbdabf;border-radius:6px;background:#edf3e5;color:#486238;cursor:pointer}.resources{min-width:0;min-height:0}.contained .resources{flex:1;overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable;padding-right:3px}.resources:focus-visible{outline:2px solid #74994e;outline-offset:-2px}button:disabled,input:disabled,select:disabled{opacity:.45;cursor:default}button:focus-visible,summary:focus-visible,select:focus-visible{outline:2px solid #74994e;outline-offset:2px}
</style>
